370	+package hotel.reservations;
371	+
372	+import hotel.rooms.Room;
373	+import hotel.rooms.RoomType;
374	+import java.math.BigDecimal;
375	+import java.time.DayOfWeek;
376	+import java.time.LocalDate;
377	+import java.time.temporal.ChronoUnit;
378	+import java.util.Map;
379	+
380	+final class WeekendPackageStrategy implements RatePlanStrategy {
381	+
382	+    private static final Map<RoomType, BigDecimal> PACKAGE_PRICES = Map.of(
383	+            RoomType.STANDARD, new BigDecimal("520.00"),
384	+            RoomType.DELUXE, new BigDecimal("820.00"),
385	+            RoomType.SUITE, new BigDecimal("1200.00"));
386	+
387	+    @Override
388	+    public void validate(NewReservation request, Room room) {
389	+        if (request.checkIn().getDayOfWeek() != DayOfWeek.FRIDAY) {
390	+            throw new HotelException(
391	+                    ErrorCode.INVALID_REQUEST, "weekend package must start on Friday");
392	+        }
393	+        if (request.checkOut().getDayOfWeek() != DayOfWeek.SUNDAY) {
394	+            throw new HotelException(
395	+                    ErrorCode.INVALID_REQUEST, "weekend package must end on Sunday");
396	+        }
397	+        long nights = ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
398	+        if (nights != 2) {
399	+            throw new HotelException(
400	+                    ErrorCode.INVALID_REQUEST, "weekend package must be exactly 2 nights");
401	+        }
402	+    }
403	+
404	+    @Override
405	+    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, NewReservation request) {
406	+        BigDecimal packagePrice = PACKAGE_PRICES.get(room.type());
407	+        return new Price(2, packagePrice, PriceCalculator.cents(BigDecimal.ZERO), packagePrice);
408	+    }
409	+
410	+    @Override
411	+    public BigDecimal refundAmount(BigDecimal amountPaid) {
412	+        return PriceCalculator.cents(amountPaid.divide(new BigDecimal("2")));
413	+    }
414	+}
