+        assertEquals(ErrorCode.INVALID_REQUEST, invalidCode.errorCode());
+    }
+
+    @Test
+    void corporateRateRefundsFullAmount() {
+        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-12", RatePlan.CORPORATE, "TECNOSUL"));
